// Bẫy: static collection là GC root -> mọi thứ bên trong sống mãi
public class Registry {
    private static final List<Session> ALL = new ArrayList<>(); // rò rỉ nếu không bao giờ xoá
}

// Class chỉ initialize khi thực sự cần -> nền tảng của holder idiom
public class Singleton {
    private Singleton() {}
    private static class Holder {
        static final Singleton INSTANCE = new Singleton();   // <clinit> chạy đúng 1 lần, thread-safe
    }
    public static Singleton getInstance() { return Holder.INSTANCE; }
}

