// Escape analysis: object này có thể không bao giờ được cấp phát trên heap
public double distance(double x, double y) {
    Point p = new Point(x, y);   // không thoát khỏi method -> scalar replacement
    return Math.sqrt(p.x() * p.x() + p.y() * p.y());
}

